"""Refine and fix UI translations for Splinter Cell Chaos Theory Thai Translation Mod.

Fixes:
1. OnlineTermsOfUse in pregame_pc.json (realign all keys, fix mistranslations, preserve bullets and tabs).
2. Whitespace preservation across all UI files (trailing spaces, leading spaces, tabs).
3. Newline count in credits.json (T_Credit18).
4. Phrasing refinement in MenuBioAmon (Bio1 ex-pat mistranslation).
5. Phrasing refinement in credits.json (T_Credit15).
"""

from __future__ import annotations
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
UI_DIR = ROOT / "data" / "translations" / "ui"


def fix_credits():
    path = UI_DIR / "credits.json"
    data = json.loads(path.read_text(encoding="utf-8"))
    sec = data["sections"]["Credit"]

    # T_Credit18: newline count was 39 vs 38
    en18 = sec["T_Credit18"]["en"]
    th18 = (
        "ขอขอบคุณเป็นพิเศษ\\n \\n"
        "ผู้ช่วยโปรดิวเซอร์\\n\\n\\n\\n"
        "ฝ่ายบริการทางเทคนิค\\n\\n\\n\\n"
        "วิจัยการทดสอบเล่นฝ่ายการตลาด\\n\\n\\n\\n"
        "ฝ่ายสนับสนุนอื่นๆ\\n \\n"
        "RAD Video Tools - \\n"
        "Bink Video (เครื่องหมายการค้าของ RAD Game Tools)"
        "\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n "
    )
    c_th = th18.count("\\n")
    c_en = en18.count("\\n")
    assert c_th == c_en, f"T_Credit18 nl mismatch: {c_th} vs {c_en}"
    sec["T_Credit18"]["th"] = th18

    # T_Credit15: improve EMEA Senior Marketing Group Manager
    en15 = sec["T_Credit15"]["en"]
    th15 = (
        "ฝ่ายการตลาด EMEA\\n \\n"
        "ผู้อำนวยการฝ่ายการตลาด EMEA\\n\\n\\n\\n"
        "ผู้จัดการกลุ่มการตลาดอาวุโส \\n"
        "ภูมิภาค EMEA\\n\\n\\n\\n"
        "ผู้จัดการอาวุโสฝ่ายแบรนด์ EMEA\\n\\n\\n\\n"
        "ผู้จัดการฝ่ายแบรนด์ EMEA\\n\\n\\n\\n"
        "ผู้จัดการฝ่ายแบรนด์ประจำภูมิภาค\\n\\n\\n\\n"
        "ขอขอบคุณเป็นพิเศษ\\n\\n\\n\\n"
    )
    assert th15.count("\\n") == en15.count("\\n")
    sec["T_Credit15"]["th"] = th15

    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("Fixed credits.json")


def fix_loading_screens():
    path = UI_DIR / "loading_screens.json"
    data = json.loads(path.read_text(encoding="utf-8"))

    # Trailing spaces
    data["sections"]["03_bank"]["Tip0"]["th"] = "สามารถใช้กล้อง EEV แฮกวัตถุจากระยะไกลได้ แต่จะทำได้ยากกว่าปกติ "
    data["sections"]["03_chembunker"]["Tip1"]["th"] = "การโรยตัวคู่เป็นวิธีที่ดีที่สุดในการขึ้นสู่พื้นที่สูงหรือลงสู่พื้นที่ต่ำ "
    data["sections"]["04_gcs"]["Tip3"]["th"] = "คุณทั้งสองคนต้องร่วมมือกันอย่างใกล้ชิดจึงจะสามารถทำภารกิจให้สำเร็จได้ "

    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("Fixed loading_screens.json")


def fix_pregame_menus():
    path = UI_DIR / "pregame_menus.json"
    data = json.loads(path.read_text(encoding="utf-8"))

    # Trailing spaces
    data["sections"]["OPTIONSTITLE"]["SoundEffectsVolume"]["th"] = "ระดับเสียงเอฟเฟกต์ / เสียงพูด "
    data["sections"]["RECENTPLAYERS"]["PlayerOptionsCaption"]["th"] = "ตัวเลือกผู้เล่น "
    data["sections"]["LOADSAVE"]["DeleteSaveMsg"]["th"] = "คุณแน่ใจหรือไม่ว่าต้องการลบความคืบหน้านี้? "
    data["sections"]["LOADSAVE"]["DeleteAllSavesMsg"]["th"] = "คุณแน่ใจหรือไม่ว่าต้องการลบความคืบหน้าทั้งหมดของคุณ? "
    data["sections"]["LOADOUT"]["LoadOutAttachSelTitle"]["th"] = "เลือกอุปกรณ์เสริม "

    path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print("Fixed pregame_menus.json")


def fix_pregame_pc():
    path = UI_DIR / "pregame_pc.json"
    data = json.loads(path.read_text(encoding="utf-8"))

    # 1. MenuBioAmon refinements and trailing spaces
    bio = data["sections"]["MenuBioAmon"]
    bio["Bio1"]["th"] = (
        "ย้อนกลับไปในช่วงกลางทศวรรษ 90 หนุ่มหน้าใสชาวบราซิลพลัดถิ่นที่อาศัยอยู่ในสหราชอาณาจักรตัดสินใจวางฮาร์โมนิกา "
        "หันมาจับเครื่องแซมเปิล และตั้งชื่อนามแฝงตามนิยายของสตีเฟน คิง อัลบั้มที่เกิดขึ้นคือ 'Adventures In Foam' ของ Cujo "
        "(วางจำหน่ายภายใต้ค่าย Ninebar records และต่อมาออกใหม่กับ Ninja Tune) ถือเป็นจุดเริ่มต้นการเข้าสู่วงการดนตรีของ Amon Tobin "
        "ที่จริงยังมีโปรเจกต์ก่อนหน้า Cujo อีกด้วย แต่ทุกคนรู้ดีว่าอย่าพูดถึงมัน... แต่ถ้าคุณทำให้ Amon เมาแอ๋ได้ล่ะก็... "
        "จริงๆ ก็ไม่หรอก ต่อให้เมาแค่ไหนเขาก็ไม่เปิดให้คุณฟังอยู่ดี "
    )
    bio["Bio2"]["th"] = bio["Bio2"]["th"].rstrip(" ") + " "
    bio["Bio3"]["th"] = bio["Bio3"]["th"].rstrip(" ") + " "
    bio["Bio5"]["th"] = bio["Bio5"]["th"].rstrip(" ") + " "
    bio["Bio7"]["th"] = bio["Bio7"]["th"].rstrip(" ") + "  "

    # 2. FRIENDSLIST ErrorFriendsNoPlayerScore (5 trailing spaces)
    data["sections"]["FRIENDSLIST"]["ErrorFriendsNoPlayerScore"]["th"] = "ผู้เล่นไม่มีคะแนนในฐานข้อมูล     "

